// chunk split inside escaped quote and CRLF
let p = createParser();
assert.deepEqual(p.push('\"a\"'), []);
assert.deepEqual(p.push('\"b\",c\r'), [['a\"b', 'c']]);
assert.deepEqual(p.push('\n'), []);
assert.deepEqual(p.push('d'), []);
assert.deepEqual(p.end(), [['d']]);

// lone CR and LF separators, empty lines
assert.deepEqual(parse('a\rb\n\nc'), [['a'], ['b'], [''], ['c']]);
assert.deepEqual(parse('\n'), [['']]);
assert.deepEqual(parse('\n\n'), [[''], ['']]);
assert.deepEqual(parse(''), []);
assert.deepEqual(parse('﻿'), []);
assert.deepEqual(parse('a,'), [['a', '']]);

// BOM only at very start, after empty chunks
p = createParser();
p.push('');
assert.deepEqual(p.push('﻿x\n'), [['x']]);
p = createParser();
assert.deepEqual(p.push('a,﻿b\n'), [['a', '﻿b']]);

// quoted CRLF preserved, counted once for line numbers
p = createParser();
assert.deepEqual(p.push('\"x\r\ny\" z'), (() => { throw 0; })());
